<?php
$active_menu='employee';
include 'header.php';
require_once __DIR__.'/../foundation.php';
oecrm_require_permission($conn,'employee_profiles','view');
$employeeId=oecrm_int_param($_GET,'id');
$stmt=mysqli_prepare($conn,'SELECT e.*,p.*,c.display_name company_name,d.name department_name FROM employeestbl e LEFT JOIN employee_profiles p ON p.employee_id=e.id LEFT JOIN companies c ON c.id=e.company_id LEFT JOIN departments d ON d.id=e.department_id WHERE e.id=?');
mysqli_stmt_bind_param($stmt,'i',$employeeId);mysqli_stmt_execute($stmt);$employee=mysqli_fetch_assoc(mysqli_stmt_get_result($stmt));mysqli_stmt_close($stmt);
if(!$employee){http_response_code(404);exit('Employee not found.');}
$message=$_SESSION['employee_flash']??'';unset($_SESSION['employee_flash']);
$contracts=mysqli_query($conn,'SELECT * FROM employee_contracts WHERE employee_id='.(int)$employeeId.' ORDER BY id DESC');
$increments=mysqli_query($conn,'SELECT * FROM employee_increments WHERE employee_id='.(int)$employeeId.' ORDER BY effective_date DESC,id DESC');
$documents=mysqli_query($conn,'SELECT * FROM employee_documents WHERE employee_id='.(int)$employeeId.' ORDER BY id DESC');
?>
