e="<?php echo oecrm_h($employee['blood_group']);?>"></div><div class="form-group"><label>Marital Status</label><select class="form-control" name="marital_status"><option value="">Select</option><?php foreach(['single','married','divorced','widowed'] as $v):?><option <?php echo ($employee['marital_status']??'')===$v?'selected':'';?>><?php echo ucwords($v);?></option><?php endforeach;?></select></div><div class="form-group span-2"><label>Current Address</label><textarea class="form-control" name="current_address"><?php echo oecrm_h($employee['current_address']);?></textarea></div><div class="form-group span-2"><label>Permanent Address</label><textarea class="form-control" name="permanent_address"><?php echo oecrm_h($employee['permanent_address']);?></textarea></div></div><div class="profile-form-actions"><button class="btn btn-primary"><i class="fa fa-save"></i> Save Employment Details</button></div></form></div></div>
